// make_savings_qr.cjs - KV_SAVINGS_QR: Savings QR vault (print pre-signed QRs, key deleted, scan to send to hot wallet)
// Writes kv_savings_core.ts, kv_savings_qr.ts, SavingsQRScreen.tsx and wires AppNaviagator + GenerateVaultScreen.
// The two-phone FROST vault is not touched. Run from the app folder:  node make_savings_qr.cjs
// Installs expo-print + qrcode if missing (expo-print is native -> new dev build).
// Also: slips print KAS + USD value; first deposit requires matching hot-wallet backup cards.
// Also: Move funds to hot wallet for old card + paper vaults; Create Vault refuses to overwrite a funded vault.
const fs = require('fs');
const FILES = {
"kv_savings_core.ts": "// ============================================================================\n// kv_savings_core.ts — KV_SAVINGS_QR pure logic (no storage, no network, no UI)\n// ============================================================================\n// Savings QR: a throwaway key receives a deposit from the hot wallet, pre-signs\n// one transaction per coin that pays ONLY the hot wallet, the QRs are printed,\n// and the key is deleted. Afterwards no key exists: each printed QR is the only\n// way to move its coin, and it can only move it to the hot wallet.\n//\n// QR text (one coin):\n//   KVSQ1|<net>|<coinXonly>|<coinTxId>|<coinIndex>|<coinSompi>|<outSompi>|<hotXonly>|<sig>\n// Everything in it is public except that it is a finished, signed spend.\n// The signature is checked on the phone before anything is broadcast.\n// ============================================================================\n\nimport { schnorr, secp256k1 } from '@noble/curves/secp256k1';\nimport { bytesToHex, hexToBytes } from '@noble/hashes/utils';\nimport { computeSighash, computeTxId, storageMass } from './kaspa_rest_tx';\n\nexport type SqNet = 'mainnet' | 'testnet-10' | 'testnet-11';\nexport const SQ_PREFIX = 'KVSQ1';\nexport const SQ_FEE_RATE = 300n;          // sompi/gram = 3x the Toccata floor (100) so QRs still pass years later\nexport const SQ_MIN_COIN = 100_000_000n;  // 1 KAS per QR minimum (keeps KIP-9 storage mass low)\nexport const SQ_MAX_QRS = 10;\nexport const SQ_MAX_MASS = 90_000n;       // stay under the 100k standard limit\nconst SUBNET = '0000000000000000000000000000000000000000';\nconst SIG_SCRIPT_LEN = 66;                // push(65) + 64-byte schnorr sig + sighash type\n\nexport interface SqCoin { txId: string; index: number; amount: bigint; }\nexport interface SqQr {\n  net: SqNet; coinXonly: string; coinTxId: string; coinIndex: number;\n  coinSompi: bigint; outSompi: bigint; hotXonly: string; sig: string;\n}\n\nconst isHex = (s: string, n: number) => typeof s === 'string' && s.length === n && /^[0-9a-f]+$/.test(s);\nexport const p2pk = (xonlyHex: string) => '20' + xonlyHex + 'ac';\n\n// --- mass / fee ---------------------------------------------------------------\nfunction txBytes(nIn: number, nOut: number): bigint {\n  // version 2 + in count 8 + per input (32+4+8+66+8) + out count 8 + per output (8+2+8+34)\n  // + lockTime 8 + subnetwork 20 + gas 8 + payload hash 32 + payload len 8\n  return BigInt(94 + nIn * (52 + SIG_SCRIPT_LEN) + nOut * 52);\n}\nfunction computeMassP2pk(nIn: number, nOut: number): bigint {\n  return txBytes(nIn, nOut) + BigInt(nOut) * 36n * 10n + BigInt(nIn) * 1000n;\n}\n/** Fee for a P2PK tx with these input/output values (fee taken from the inputs). */\nexport function sqFee(inValues: bigint[], outValues: bigint[]): { fee: bigint; mass: bigint } {\n  const c = computeMassP2pk(inValues.length, outValues.length);\n  const s = storageMass(inValues, outValues);\n  const t = 2n * txBytes(inValues.length, outValues.length);\n  let mass = c; if (s > mass) mass = s; if (t > mass) mass = t;\n  return { fee: mass * SQ_FEE_RATE, mass };\n}\n/** Fee of one exit (1 coin -> hot wallet). Depends only weakly on the amount. */\nexport function sqExitFee(coin: bigint): bigint {\n  // iterate once: storage mass depends on the output value\n  let f = sqFee([coin], [coin - 1_000_000n]).fee;\n  f = sqFee([coin], [coin - f]).fee;\n  return f;\n}\n\n// --- signing ------------------------------------------------------------------\nfunction signP2pkTx(privHex: string, inputs: SqCoin[], outputs: { amount: bigint; xonly: string }[]) {\n  const priv = hexToBytes(privHex);\n  const xonly = bytesToHex(secp256k1.getPublicKey(priv, true).slice(1));\n  const inScript = hexToBytes(p2pk(xonly));\n  const ins = inputs.map((u) => ({ txId: hexToBytes(u.txId), index: u.index, sequence: 0n, sigOpCount: 1, scriptVersion: 0, scriptPubKey: inScript, value: u.amount }));\n  const outs = outputs.map((o) => ({ value: o.amount, scriptVersion: 0, script: hexToBytes(p2pk(o.xonly)) }));\n  const sigs: string[] = [];\n  for (let i = 0; i < ins.length; i++) {\n    const h = computeSighash(0, ins, outs, i, hexToBytes(SUBNET), 0n, 0n, true, new Uint8Array(0));\n    sigs.push(bytesToHex(schnorr.sign(h, priv)));\n  }\n  priv.fill(0);\n  const tx = {\n    version: 0,\n    inputs: inputs.map((u, i) => ({ previousOutpoint: { transactionId: u.txId, index: u.index }, signatureScript: '41' + sigs[i] + '01', sequence: '0', sigOpCount: 1 })),\n    outputs: outputs.map((o) => ({ amount: o.amount.toString(), scriptPublicKey: { version: 0, scriptPublicKey: p2pk(o.xonly) } })),\n    lockTime: '0', subnetworkId: SUBNET, gas: '0', payload: '',\n  };\n  const txId = computeTxId({\n    version: 0,\n    inputs: inputs.map((u) => ({ prevTxId: u.txId, prevIndex: u.index, sequence: 0n })),\n    outputs: outputs.map((o) => ({ amount: o.amount, scriptVersion: 0, scriptHex: p2pk(o.xonly) })),\n    lockTime: 0n, subnetworkId: SUBNET, gas: 0n, payloadHex: '',\n  });\n  return { tx, txId, sigs, xonly };\n}\n\n/** Plan the deposit: split the funded coins into n equal coins (or use the single coin as is). */\nexport function sqPlan(funded: SqCoin[], n: number): { error?: string; split?: { coinValues: bigint[]; fee: bigint }; coins?: bigint[] } {\n  if (!Number.isInteger(n) || n < 1 || n > SQ_MAX_QRS) return { error: 'Choose 1 to ' + SQ_MAX_QRS + ' QRs.' };\n  if (!funded.length) return { error: 'The deposit has not arrived yet.' };\n  const total = funded.reduce((a, c) => a + c.amount, 0n);\n  if (n === 1 && funded.length === 1) {\n    if (total < SQ_MIN_COIN) return { error: 'Each QR must hold at least 1 KAS.' };\n    return { coins: [total] };\n  }\n  // split: guess fee, size coins, recompute until stable\n  let fee = 0n; let vals: bigint[] = [];\n  for (let k = 0; k < 4; k++) {\n    const each = (total - fee) / BigInt(n);\n    vals = Array.from({ length: n }, (_, i) => (i === n - 1 ? total - fee - each * BigInt(n - 1) : each));\n    const f = sqFee(funded.map((c) => c.amount), vals);\n    if (f.mass > SQ_MAX_MASS) return { error: 'Too many QRs for this amount - use fewer QRs or a larger deposit.' };\n    if (f.fee <= fee) break;\n    fee = f.fee;\n  }\n  if (vals.some((v) => v < SQ_MIN_COIN)) return { error: 'Each QR must hold at least 1 KAS - use fewer QRs or a larger deposit.' };\n  return { split: { coinValues: vals, fee }, coins: vals };\n}\n\n/** Sign the split (if any) and one exit per coin. Pure: returns everything to broadcast/print. */\nexport function sqSignAll(p: { privHex: string; net: SqNet; funded: SqCoin[]; n: number; hotXonly: string }):\n  { error: string } | { splitTx: any | null; splitTxId: string | null; qrs: string[]; exits: { txId: string; outSompi: bigint; coin: SqCoin }[]; coinXonly: string } {\n  if (!isHex(p.hotXonly, 64)) return { error: 'Hot wallet key is not a standard (Schnorr P2PK) address.' };\n  const plan = sqPlan(p.funded, p.n);\n  if (plan.error || !plan.coins) return { error: plan.error || 'Plan failed' };\n  const coinXonly = bytesToHex(secp256k1.getPublicKey(hexToBytes(p.privHex), true).slice(1));\n  let coins: SqCoin[]; let splitTx: any = null; let splitTxId: string | null = null;\n  if (plan.split) {\n    const s = signP2pkTx(p.privHex, p.funded, plan.split.coinValues.map((v) => ({ amount: v, xonly: coinXonly })));\n    splitTx = s.tx; splitTxId = s.txId;\n    coins = plan.split.coinValues.map((v, i) => ({ txId: s.txId, index: i, amount: v }));\n  } else {\n    coins = [p.funded[0]];\n  }\n  const qrs: string[] = []; const exits: { txId: string; outSompi: bigint; coin: SqCoin }[] = [];\n  for (const c of coins) {\n    const fee = sqExitFee(c.amount);\n    const out = c.amount - fee;\n    if (out < SQ_MIN_COIN / 2n) return { error: 'Coin too small after fee.' };\n    const e = signP2pkTx(p.privHex, [c], [{ amount: out, xonly: p.hotXonly }]);\n    qrs.push([SQ_PREFIX, p.net, coinXonly, c.txId, String(c.index), c.amount.toString(), out.toString(), p.hotXonly, e.sigs[0]].join('|'));\n    exits.push({ txId: e.txId, outSompi: out, coin: c });\n  }\n  return { splitTx, splitTxId, qrs, exits, coinXonly };\n}\n\n/** Parse + verify a Savings QR's signature (no network). */\nexport function sqParse(raw: string): { error: string } | { qr: SqQr; tx: any; txId: string } {\n  const parts = String(raw || '').trim().split('|');\n  if (parts.length !== 9 || parts[0] !== SQ_PREFIX) return { error: 'Not a KasVillage Savings QR.' };\n  const [, net, coinXonly, coinTxId, idxS, coinS, outS, hotXonly, sig] = parts;\n  if (!['mainnet', 'testnet-10', 'testnet-11'].includes(net)) return { error: 'Unknown network in QR.' };\n  if (!isHex(coinXonly, 64) || !isHex(coinTxId, 64) || !isHex(hotXonly, 64) || !isHex(sig, 128)) return { error: 'Damaged QR (bad field).' };\n  if (!/^\\d{1,4}$/.test(idxS) || !/^\\d{1,19}$/.test(coinS) || !/^\\d{1,19}$/.test(outS)) return { error: 'Damaged QR (bad number).' };\n  const coinSompi = BigInt(coinS), outSompi = BigInt(outS), coinIndex = Number(idxS);\n  if (outSompi <= 0n || outSompi >= coinSompi) return { error: 'Damaged QR (amounts).' };\n  const ins = [{ txId: hexToBytes(coinTxId), index: coinIndex, sequence: 0n, sigOpCount: 1, scriptVersion: 0, scriptPubKey: hexToBytes(p2pk(coinXonly)), value: coinSompi }];\n  const outs = [{ value: outSompi, scriptVersion: 0, script: hexToBytes(p2pk(hotXonly)) }];\n  const h = computeSighash(0, ins, outs, 0, hexToBytes(SUBNET), 0n, 0n, true, new Uint8Array(0));\n  let ok = false; try { ok = schnorr.verify(hexToBytes(sig), h, hexToBytes(coinXonly)); } catch { ok = false; }\n  if (!ok) return { error: 'This QR\\'s signature does not check out - it may be damaged or not genuine.' };\n  const tx = {\n    version: 0,\n    inputs: [{ previousOutpoint: { transactionId: coinTxId, index: coinIndex }, signatureScript: '41' + sig + '01', sequence: '0', sigOpCount: 1 }],\n    outputs: [{ amount: outSompi.toString(), scriptPublicKey: { version: 0, scriptPublicKey: p2pk(hotXonly) } }],\n    lockTime: '0', subnetworkId: SUBNET, gas: '0', payload: '',\n  };\n  const txId = computeTxId({ version: 0, inputs: [{ prevTxId: coinTxId, prevIndex: coinIndex, sequence: 0n }], outputs: [{ amount: outSompi, scriptVersion: 0, scriptHex: p2pk(hotXonly) }], lockTime: 0n, subnetworkId: SUBNET, gas: 0n, payloadHex: '' });\n  return { qr: { net: net as SqNet, coinXonly, coinTxId, coinIndex, coinSompi, outSompi, hotXonly, sig }, tx, txId };\n}\n\n/** Sweep everything at the throwaway address back to the hot wallet (used to cancel before the key is forgotten). */\nexport function sqSignSweepBack(privHex: string, funded: SqCoin[], hotXonly: string): { error: string } | { tx: any; txId: string } {\n  if (!funded.length) return { error: 'Nothing to return.' };\n  const total = funded.reduce((a, c) => a + c.amount, 0n);\n  let fee = sqFee(funded.map((c) => c.amount), [total - 1_000_000n]).fee;\n  fee = sqFee(funded.map((c) => c.amount), [total - fee]).fee;\n  if (total - fee <= 0n) return { error: 'Too small to return.' };\n  const s = signP2pkTx(privHex, funded, [{ amount: total - fee, xonly: hotXonly }]);\n  return { tx: s.tx, txId: s.txId };\n}\n\n/** Kaspa P2PK address payload (x-only key) from an address string, or '' if not P2PK. */\nexport function sqXonlyFromAddress(address: string): string {\n  const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';\n  const i = String(address || '').indexOf(':'); if (i < 0) return '';\n  const d: number[] = []; for (const ch of address.slice(i + 1)) { const v = CHARSET.indexOf(ch); if (v < 0) return ''; d.push(v); }\n  const p5 = d.slice(0, d.length - 8);\n  let bits = 0, acc = 0; const p8: number[] = [];\n  for (const v of p5) { acc = (acc << 5) | v; bits += 5; while (bits >= 8) { bits -= 8; p8.push((acc >> bits) & 0xff); acc &= (1 << bits) - 1; } }\n  if (p8.length !== 33 || p8[0] !== 0x00) return '';\n  return bytesToHex(new Uint8Array(p8.slice(1)));\n}\n",
"kv_savings_qr.ts": "// ============================================================================\n// kv_savings_qr.ts — KV_SAVINGS_QR: deposit / print / verify-forget / spend\n// ============================================================================\n// Lifecycle of one deposit (one \"session\"):\n//   created  -> throwaway key saved on this phone (so a crash never strands funds)\n//   funded   -> the hot wallet paid the throwaway address (address is never shown)\n//   signed   -> split (if any) broadcast, one exit per coin signed -> QRs ready to print\n//   verified -> a printed QR scanned back + every coin confirmed on chain\n//               -> the throwaway key is DELETED; only public tracker rows remain\n// Before \"verified\" the deposit can always be returned to the hot wallet.\n// The two-phone FROST vault is not touched by any of this.\n// ============================================================================\n\nimport * as SecureStore from 'expo-secure-store';\nimport { bytesToHex } from '@noble/hashes/utils';\nimport { secp256k1 } from '@noble/curves/secp256k1';\nimport { sqSignAll, sqParse, sqSignSweepBack, sqXonlyFromAddress, SqCoin, SqNet } from './kv_savings_core';\n\nconst SESSION_KEY = 'kv_sq_session';\nconst LIST_KEY = 'kv_sq_list';\nconst SECRET_OPTS = { keychainAccessible: SecureStore.WHEN_PASSCODE_SET_THIS_DEVICE_ONLY } as any;\nconst API: Record<string, string> = { 'mainnet': 'https://api.kaspa.org', 'testnet-10': 'https://api-tn10.kaspa.org', 'testnet-11': 'https://api-tn11.kaspa.org' };\n\nexport interface SqSession {\n  v: 1; net: SqNet; priv: string; xonly: string; addr: string; n: number;\n  depositSompi: string; stage: 'created' | 'funded' | 'signed';\n  fundTxId?: string; splitTxId?: string | null; qrs?: string[];\n  exits?: { txId: string; outSompi: string; coin: { txId: string; index: number; amount: string } }[];\n  createdAt: number;\n}\nexport interface SqRow {\n  id: string; net: SqNet; addr: string; coinTxId: string; coinIndex: number; outSompi: string;\n  hotLast6: string; label: string; createdAt: number; status?: 'unspent' | 'spent' | 'unknown';\n}\n\nexport function sqActiveNet(): SqNet { return require('./kv_vault_active').kvActiveNet(); }\nexport function sqTutorial(): boolean { try { return !!require('./kv_tutorial').kvIsTutorial(); } catch { return false; } }\n\nexport async function sqHotAddress(): Promise<string> {\n  const h = (await SecureStore.getItemAsync('kv_kaspa_address')) || '';\n  return sqActiveNet() === 'mainnet' ? ((await SecureStore.getItemAsync('kaspa_address_real')) || h) : h;\n}\n\nexport async function sqLoadSession(): Promise<SqSession | null> {\n  try { const r = await SecureStore.getItemAsync(SESSION_KEY); return r ? JSON.parse(r) : null; } catch { return null; }\n}\nasync function saveSession(s: SqSession) { await SecureStore.setItemAsync(SESSION_KEY, JSON.stringify(s), SECRET_OPTS); }\n\nexport async function sqList(): Promise<SqRow[]> {\n  try { const r = await SecureStore.getItemAsync(LIST_KEY); const a = r ? JSON.parse(r) : []; return Array.isArray(a) ? a : []; } catch { return []; }\n}\nasync function saveList(rows: SqRow[]) { await SecureStore.setItemAsync(LIST_KEY, JSON.stringify(rows.slice(-200))); }\n\nasync function fetchUtxos(net: string, addr: string): Promise<SqCoin[]> {\n  const r = await fetch(API[net] + '/addresses/' + addr + '/utxos');\n  if (!r.ok) throw new Error('UTXO lookup failed (' + r.status + ')');\n  const j: any[] = await r.json();\n  return (Array.isArray(j) ? j : []).map((u: any) => ({ txId: String(u.outpoint?.transactionId || ''), index: Number(u.outpoint?.index ?? 0), amount: BigInt(u.utxoEntry?.amount || '0') }))\n    .filter((c) => /^[0-9a-f]{64}$/.test(c.txId) && c.amount > 0n);\n}\nasync function txLanded(net: string, txId: string): Promise<boolean> {\n  try { const r = await fetch(API[net] + '/transactions/' + txId + '?inputs=false&outputs=false'); return r.ok; } catch { return false; }\n}\n/** Broadcast a signed tx; an ambiguous failure is resolved by looking the txid up. */\nasync function broadcast(net: SqNet, tx: any, txId: string): Promise<{ ok: boolean; maybe?: boolean; error?: string }> {\n  try {\n    const r = await fetch(API[net] + '/transactions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ transaction: tx, allowOrphan: false }) });\n    if (r.ok) return { ok: true };\n    const body = await r.text();\n    for (let i = 0; i < 3; i++) { await new Promise((s) => setTimeout(s, 2500)); if (await txLanded(net, txId)) return { ok: true }; }\n    return { ok: false, error: 'Submit failed (' + r.status + '): ' + body.slice(0, 200) };\n  } catch (e: any) {\n    for (let i = 0; i < 3; i++) { await new Promise((s) => setTimeout(s, 2500)); if (await txLanded(net, txId)) return { ok: true }; }\n    return { ok: false, maybe: true, error: 'No answer from the network - it may still land. Check again before retrying.' };\n  }\n}\n\n/** Every Savings QR pays the hot wallet, so the hot wallet's backup cards must restore THAT wallet.\n *  '' = ok: a seed exists on this phone and it derives exactly the hot wallet address. */\nexport async function sqHotBackupCheck(): Promise<string> {\n  const m = await SecureStore.getItemAsync('kv_mnemonic');\n  if (!m) return 'Your hot wallet has no backup seed on this phone, so backup cards cannot be made for it. Savings QR pays only the hot wallet, so it is off for this wallet.';\n  const hot = await sqHotAddress();\n  const { previewAddressFromMnemonic } = require('./wallet_registration_v2');\n  const pv = await previewAddressFromMnemonic(m, sqActiveNet());\n  if (!pv?.address || !hot || pv.address.split(':')[1] !== hot.split(':')[1]) return 'Your backup seed does not restore this hot wallet (' + hot.slice(-6) + '). Do not use Savings QR until this is fixed.';\n  return '';\n}\n\n// --- 1. start: make the throwaway key and pay it from the hot wallet --------------------------\nexport async function sqStartDeposit(depositSompi: bigint, n: number): Promise<{ error?: string }> {\n  if (sqTutorial()) return { error: 'Savings QR needs Real mode.' };\n  const bk = await sqHotBackupCheck(); if (bk) return { error: bk };\n  if (await sqLoadSession()) return { error: 'Finish (or return) the deposit already in progress first.' };\n  const hot = await sqHotAddress();\n  if (!sqXonlyFromAddress(hot)) return { error: 'Your hot wallet address is not a standard address - Savings QR cannot pay it.' };\n  const net = sqActiveNet();\n  const privB = (secp256k1 as any).utils.randomPrivateKey() as Uint8Array;\n  const priv = bytesToHex(privB); privB.fill(0);\n  const xonly = bytesToHex(secp256k1.getPublicKey(require('@noble/hashes/utils').hexToBytes(priv), true).slice(1));\n  const { kaspaAddressFromXOnly } = require('./wallet_registration_v2');\n  const addr = kaspaAddressFromXOnly(require('@noble/hashes/utils').hexToBytes(xonly), net.startsWith('testnet') ? 'kaspatest' : 'kaspa');\n  if (String(addr).split(':')[0] !== String(hot).split(':')[0]) return { error: 'Network mismatch between hot wallet and vault.' };\n  // Save the key BEFORE any coin moves: a crash after funding must never strand the deposit.\n  await saveSession({ v: 1, net, priv, xonly, addr, n, depositSompi: depositSompi.toString(), stage: 'created', createdAt: Date.now() });\n  const { sendKASWithHybridSig } = require('./kasvillage_cold_wallet');\n  const r = await sendKASWithHybridSig(addr, depositSompi, 'Savings QR deposit'); // Face ID + simulation\n  if (!r?.success) {\n    // Keep the key: a send that \"failed\" may still land. \"Return deposit\" clears it safely later.\n    return { error: (r?.error || 'Deposit failed.') + ' If the deposit was cancelled, tap \"Return deposit\" to clear it.' };\n  }\n  const s = await sqLoadSession(); if (s) { s.stage = 'funded'; s.fundTxId = r.kaspaTxId || ''; await saveSession(s); }\n  return {};\n}\n\n// --- 2. sign: once the deposit is on chain, split + sign one exit per coin --------------------\nexport async function sqSign(): Promise<{ error?: string; waiting?: boolean }> {\n  const s = await sqLoadSession(); if (!s) return { error: 'No deposit in progress.' };\n  if (s.stage === 'signed') return {};\n  const funded = await fetchUtxos(s.net, s.addr);\n  if (!funded.length) return { waiting: true };\n  const hot = await sqHotAddress(); const hotXonly = sqXonlyFromAddress(hot);\n  const r = sqSignAll({ privHex: s.priv, net: s.net, funded, n: s.n, hotXonly });\n  if ('error' in r) return { error: r.error };\n  // self-check every QR before anything is broadcast\n  for (const q of r.qrs) { const p = sqParse(q); if ('error' in p) return { error: 'Self-check failed: ' + p.error }; }\n  if (r.splitTx && r.splitTxId) {\n    const b = await broadcast(s.net, r.splitTx, r.splitTxId);\n    if (!b.ok) return { error: b.error };\n  }\n  s.stage = 'signed'; s.splitTxId = r.splitTxId; s.qrs = r.qrs;\n  s.exits = r.exits.map((e) => ({ txId: e.txId, outSompi: e.outSompi.toString(), coin: { txId: e.coin.txId, index: e.coin.index, amount: e.coin.amount.toString() } }));\n  await saveSession(s);\n  return {};\n}\n\n// --- 3. verify: a printed QR scanned back + every coin on chain -> forget the key -------------\nexport async function sqVerifyAndForget(scanned: string): Promise<{ error?: string; done?: boolean }> {\n  const s = await sqLoadSession(); if (!s || s.stage !== 'signed' || !s.qrs || !s.exits) return { error: 'Nothing to verify.' };\n  if (!s.qrs.includes(String(scanned || '').trim())) return { error: 'That QR is not from this deposit. Scan one of the sheets you just printed.' };\n  const on = await fetchUtxos(s.net, s.addr);\n  const missing = s.exits.filter((e) => !on.some((u) => u.txId === e.coin.txId && u.index === e.coin.index && u.amount.toString() === e.coin.amount));\n  if (missing.length) return { error: 'Waiting for the network to confirm the coins (' + missing.length + ' left). Try again in a minute.' };\n  const hot = await sqHotAddress();\n  const rows = await sqList();\n  s.exits.forEach((e, i) => rows.push({ id: e.txId, net: s.net, addr: s.addr, coinTxId: e.coin.txId, coinIndex: e.coin.index, outSompi: e.outSompi, hotLast6: hot.slice(-6), label: (i + 1) + ' of ' + s.exits!.length, createdAt: Date.now() }));\n  await saveList(rows);\n  s.priv = ''; await saveSession(s);           // overwrite first, then delete\n  await SecureStore.deleteItemAsync(SESSION_KEY);\n  return { done: true };\n}\n\n// --- cancel: before the key is forgotten, everything can go back to the hot wallet ------------\nexport async function sqReturnToHot(): Promise<{ error?: string; done?: boolean }> {\n  const s = await sqLoadSession(); if (!s) return { error: 'No deposit in progress.' };\n  const funded = await fetchUtxos(s.net, s.addr);\n  if (!funded.length) {\n    if (s.stage === 'created' && Date.now() - s.createdAt > 120000) {\n      // never funded: check twice, 10 s apart, before dropping the key\n      await new Promise((ok) => setTimeout(ok, 10000));\n      if ((await fetchUtxos(s.net, s.addr)).length === 0) { await SecureStore.deleteItemAsync(SESSION_KEY); return { done: true }; }\n      return { error: 'Coins just arrived - tap Continue instead.' };\n    }\n    return { error: 'The deposit is not visible on chain yet. Wait a couple of minutes and try again.' };\n  }\n  const hotXonly = sqXonlyFromAddress(await sqHotAddress());\n  const r = sqSignSweepBack(s.priv, funded, hotXonly);\n  if ('error' in r) return { error: r.error };\n  const b = await broadcast(s.net, r.tx, r.txId);\n  if (!b.ok) return { error: b.error };\n  await SecureStore.deleteItemAsync(SESSION_KEY);\n  return { done: true };\n}\n\n// --- spend: scan a printed QR -> checks -> broadcast to the hot wallet -----------------------\nexport async function sqCheckQr(raw: string): Promise<{ error?: string; info?: { outSompi: bigint; paysHot: boolean; hotLast6: string; net: SqNet; txId: string; tx: any } }> {\n  const p = sqParse(raw); if ('error' in p) return { error: p.error };\n  const net = sqActiveNet();\n  if (p.qr.net !== net) return { error: 'This QR is for ' + p.qr.net + ' but the app is on ' + net + '.' };\n  const { kaspaAddressFromXOnly } = require('./wallet_registration_v2');\n  const addr = kaspaAddressFromXOnly(require('@noble/hashes/utils').hexToBytes(p.qr.coinXonly), net.startsWith('testnet') ? 'kaspatest' : 'kaspa');\n  let on: SqCoin[]; try { on = await fetchUtxos(net, addr); } catch (e: any) { return { error: e?.message || 'Network error' }; }\n  const coin = on.find((u) => u.txId === p.qr.coinTxId && u.index === p.qr.coinIndex);\n  if (!coin) return { error: (await txLanded(net, p.txId)) ? 'This QR was already used - its coins are in your hot wallet.' : 'This QR\\'s coin is not on chain (already spent, or not confirmed yet).' };\n  if (coin.amount !== p.qr.coinSompi) return { error: 'Coin amount does not match the QR.' };\n  const hot = await sqHotAddress();\n  const { kaspaAddressFromXOnly: k2 } = require('./wallet_registration_v2');\n  const pays = k2(require('@noble/hashes/utils').hexToBytes(p.qr.hotXonly), net.startsWith('testnet') ? 'kaspatest' : 'kaspa') as string;\n  return { info: { outSompi: p.qr.outSompi, paysHot: pays === hot, hotLast6: pays.slice(-6), net, txId: p.txId, tx: p.tx } };\n}\nexport async function sqSpend(info: { net: SqNet; txId: string; tx: any }): Promise<{ error?: string; maybe?: boolean; txId?: string }> {\n  const b = await broadcast(info.net, info.tx, info.txId);\n  if (!b.ok) return { error: b.error, maybe: b.maybe };\n  const rows = await sqList(); const row = rows.find((r) => r.id === info.txId); if (row) { row.status = 'spent'; await saveList(rows); }\n  return { txId: info.txId };\n}\n\n/** Refresh tracker status from the chain (public data only). */\nexport async function sqRefresh(): Promise<SqRow[]> {\n  const rows = await sqList(); const byAddr: Record<string, SqCoin[] | null> = {};\n  for (const r of rows) {\n    if (r.status === 'spent') continue;\n    if (!(r.addr in byAddr)) { try { byAddr[r.addr] = await fetchUtxos(r.net, r.addr); } catch { byAddr[r.addr] = null; } }\n    const on = byAddr[r.addr];\n    r.status = on === null ? 'unknown' : on.some((u) => u.txId === r.coinTxId && u.index === r.coinIndex) ? 'unspent' : 'spent';\n  }\n  await saveList(rows);\n  return rows;\n}\n\n/** Printable HTML: one QR per coin, two copies reminder. QR drawn as SVG (pure JS, no network). */\nexport function sqPrintHtml(qrs: string[], outs: string[], hotLast6: string, net: string, usdPerKas = 0): string {\n  const QR = require('qrcode');\n  const svg = (t: string) => {\n    const q = QR.create(t, { errorCorrectionLevel: 'M' }); const n = q.modules.size; const d = q.modules.data; const m = 4; const sz = n + 2 * m;\n    let p = ''; for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (d[y * n + x]) p += 'M' + (x + m) + ' ' + (y + m) + 'h1v1h-1z';\n    return '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ' + sz + ' ' + sz + '\" width=\"260\" height=\"260\" shape-rendering=\"crispEdges\"><rect width=\"100%\" height=\"100%\" fill=\"#fff\"/><path d=\"' + p + '\" fill=\"#000\"/></svg>';\n  };\n  const date = new Date().toISOString().slice(0, 10);\n  const cards = qrs.map((q, i) => '<div class=\"c\"><h2>KasVillage Savings QR · ' + (i + 1) + ' of ' + qrs.length + '</h2>' + svg(q) +\n    '<p class=\"k\"><b>' + (Number(outs[i]) / 1e8).toFixed(4) + ' KAS</b></p>' +\n    (usdPerKas > 0 ? '<p class=\"u\">≈ $' + ((Number(outs[i]) / 1e8) * usdPerKas).toFixed(2).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',') + ' USD on ' + date + ' (1 KAS = $' + usdPerKas.toFixed(4) + ')</p><p class=\"s\">Dollar value changes with the KAS price; the KAS amount does not.</p>' : '') +\n    '<p>To hot wallet …' + hotLast6 + '</p><p>' + net + ' · ' + date + '</p>' +\n    '<p class=\"s\">Whoever scans this can only move these coins into that wallet. Losing this paper loses these coins: keep two copies in different places.</p></div>').join('');\n  return '<html><head><meta name=\"viewport\" content=\"width=device-width\"/><style>body{font-family:sans-serif}.c{page-break-inside:avoid;border:1px solid #000;padding:12px;margin:12px 0;text-align:center}.s{font-size:11px}.k{font-size:22px;margin:6px 0}.u{font-size:16px;margin:2px 0}</style></head><body>' + cards + '</body></html>';\n}\n\n// --- old card + paper vaults (no longer created): balance, sweep amount, replace guard ---------\n/** The existing card + paper vault (if any) with its on-chain balance and an exact sweep amount. */\nexport async function sqOldCardPaperVault(): Promise<{ vault: any; sompi: bigint; sweepKas: string } | null> {\n  const VA = require('./kv_vault_active');\n  if ((await VA.kvVaultKind()) !== 'cards_paper') return null;\n  const fv = await VA.kvFrostVaultActive(); if (!fv?.address) return null;\n  const utxos = await fetchUtxos(fv.network || sqActiveNet(), fv.address);\n  const sompi = utxos.reduce((a, u) => a + u.amount, 0n);\n  // one output, no change: amount = total - vaultMinFee(inputs, 1) (same rule as vaultBuildSpendTemplate)\n  const fee = require('./frost_qr_signer').vaultMinFee(utxos.length, 1) as bigint;\n  const amt = sompi > fee ? sompi - fee : 0n;\n  const sweepKas = (amt / 100_000_000n).toString() + '.' + (amt % 100_000_000n).toString().padStart(8, '0');\n  return { vault: fv, sompi, sweepKas };\n}\n\n/** Refuse to replace a vault that still holds coins (or whose balance can't be checked). '' = ok. */\nexport async function sqVaultReplaceGuard(): Promise<string> {\n  const VA = require('./kv_vault_active');\n  const addrs: { a: string; n: string }[] = [];\n  try { const a = await VA.kvVaultAddrActive(); if (a) addrs.push({ a, n: sqActiveNet() }); } catch {}\n  try { const s = await SecureStore.getItemAsync('kv_vault_address'); if (s && !addrs.some((x) => x.a === s)) addrs.push({ a: s, n: s.startsWith('kaspatest:') ? 'testnet-10' : 'mainnet' }); } catch {}\n  for (const { a, n } of addrs) {\n    let bal: bigint;\n    try { bal = (await fetchUtxos(n, a)).reduce((x, u) => x + u.amount, 0n); } catch { return 'Could not check your current vault balance - try again online.'; }\n    if (bal > 0n) return 'Your current vault still holds ' + (Number(bal) / 1e8).toFixed(4) + ' KAS. Move it to your hot wallet first, then create a new vault.';\n  }\n  return '';\n}\n",
"SavingsQRScreen.tsx": "// ============================================================================\n// SavingsQRScreen.tsx — KV_SAVINGS_QR: the vault as a tracker of printed QRs\n// ============================================================================\n// Add to vault : hot wallet -> throwaway key -> split -> sign exits -> print -> scan back -> key deleted\n// Spend        : scan a printed QR -> signature + chain checks -> coins go to the hot wallet\n// The vault keeps no keys after a deposit is verified. The two-phone FROST vault is separate.\n// ============================================================================\n\nimport React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { View, Text, TouchableOpacity, StyleSheet, ScrollView, TextInput, Alert, ActivityIndicator } from 'react-native';\nimport * as SQ from './kv_savings_qr';\nimport { VaultQRSignScreen } from './VaultQRSignScreen';\n\ntype Mode = 'home' | 'add' | 'progress' | 'print' | 'verify' | 'scan';\n\n/** \"12.5\" / \"12,5\" -> sompi, exact (no floating point). */\nfunction kasToSompi(t: string): bigint | null {\n  const s = String(t || '').trim().replace(',', '.');\n  if (!/^\\d{1,11}(\\.\\d{0,8})?$/.test(s)) return null;\n  const [w, f = ''] = s.split('.');\n  return BigInt(w) * 100_000_000n + BigInt((f + '00000000').slice(0, 8));\n}\nconst fmt = (sompi: string | bigint) => (Number(BigInt(sompi)) / 1e8).toFixed(4);\n\nexport const SavingsQRScreen: React.FC<{ onClose: () => void }> = ({ onClose }) => {\n  const [mode, setMode] = useState<Mode>('home');\n  const [rows, setRows] = useState<SQ.SqRow[]>([]);\n  const [session, setSession] = useState<SQ.SqSession | null>(null);\n  const [amount, setAmount] = useState('');\n  const [count, setCount] = useState('1');\n  const [busy, setBusy] = useState(false);\n  const [msg, setMsg] = useState('');\n  const [camOk, setCamOk] = useState(false);\n  const scanLock = useRef(false);\n  const [oldVault, setOldVault] = useState<{ vault: any; sompi: bigint; sweepKas: string } | null>(null);\n  const [oldSweep, setOldSweep] = useState<{ to: string; kas: string } | null>(null);\n  const _cam = (() => { try { return require('expo-camera'); } catch { return null; } })();\n\n  const reload = useCallback(async () => {\n    setSession(await SQ.sqLoadSession());\n    setRows(await SQ.sqList());\n    try { setRows(await SQ.sqRefresh()); } catch {}\n    try { setOldVault(await SQ.sqOldCardPaperVault()); } catch { setOldVault(null); }\n  }, []);\n  useEffect(() => { reload(); }, [reload]);\n\n  // Block screenshots while QRs exist on this phone (print + verify steps).\n  useEffect(() => {\n    if (mode !== 'print' && mode !== 'verify') return;\n    let undo: any = null;\n    (async () => { try { const SC = await import('expo-screen-capture'); await SC.preventScreenCaptureAsync('kv-savings-qr'); undo = () => SC.allowScreenCaptureAsync('kv-savings-qr').catch(() => {}); } catch {} })();\n    return () => { if (undo) undo(); };\n  }, [mode]);\n\n  // Progress: wait for the deposit, then sign.\n  useEffect(() => {\n    if (mode !== 'progress') return;\n    let stop = false;\n    (async () => {\n      while (!stop) {\n        const r = await SQ.sqSign().catch((e: any) => ({ error: String(e?.message || e) }));\n        if (stop) return;\n        if ((r as any).error) { setMsg((r as any).error); return; }\n        if (!(r as any).waiting) { setSession(await SQ.sqLoadSession()); setMode('print'); return; }\n        setMsg('Waiting for the deposit to confirm…');\n        await new Promise((ok) => setTimeout(ok, 5000));\n      }\n    })();\n    return () => { stop = true; };\n  }, [mode]);\n\n  const askCamera = async () => { try { const r = await _cam?.Camera?.requestCameraPermissionsAsync?.(); setCamOk(r?.status === 'granted'); } catch {} };\n\n  const startDeposit = async () => {\n    const s = kasToSompi(amount); const n = Number(count);\n    if (s === null || s <= 0n) { Alert.alert('Amount', 'Enter an amount in KAS, e.g. 250 or 12.5'); return; }\n    if (!Number.isInteger(n) || n < 1 || n > 10) { Alert.alert('QRs', 'Choose 1 to 10 QRs.'); return; }\n    if (s / BigInt(n) < 101_000_000n) { Alert.alert('Too small', 'Each QR must hold at least about 1.01 KAS.'); return; }\n    // Every QR pays the hot wallet: its backup cards must exist and match before the first deposit.\n    const bk = await SQ.sqHotBackupCheck();\n    if (bk) { Alert.alert('Back up your hot wallet first', bk); return; }\n    let saved = false; try { saved = (await require('expo-secure-store').getItemAsync('kv_sq_backup_ok')) === '1'; } catch {}\n    if (!saved) {\n      const yes = await new Promise<boolean>((ok) => Alert.alert('Backup cards saved?', 'Savings QRs always pay your hot wallet. If you lose this phone, only your hot wallet backup cards (Profile → Backup cards) get those coins back. Have you saved them?', [\n        { text: 'Not yet', style: 'cancel', onPress: () => ok(false) }, { text: 'Yes, saved', onPress: () => ok(true) }]));\n      if (!yes) return;\n      try { await require('expo-secure-store').setItemAsync('kv_sq_backup_ok', '1'); } catch {}\n    }\n    setBusy(true); setMsg('');\n    const r = await SQ.sqStartDeposit(s, n);\n    setBusy(false);\n    if (r.error) { Alert.alert('Deposit', r.error); await reload(); return; }\n    setMode('progress');\n  };\n\n  const printSheet = async () => {\n    if (!session?.qrs || !session.exits) return;\n    let Print: any = null; try { Print = require('expo-print'); } catch {}\n    if (!Print?.printAsync) { Alert.alert('Printing not available', 'This build of KasVillage cannot print yet. Update the app, then come back: your deposit is safe and waiting.'); return; }\n    const hot = await SQ.sqHotAddress();\n    let usd = 0; try { const PF = require('./kas_price_feed'); await PF.refreshPrice().catch(() => {}); const p = PF.getKasPrice(); usd = p && !p.isStale ? Number(p.usdPerKas) || 0 : 0; } catch {}\n    try { await Print.printAsync({ html: SQ.sqPrintHtml(session.qrs, session.exits.map((e) => e.outSompi), hot.slice(-6), session.net, usd) }); }\n    catch (e: any) { Alert.alert('Print', String(e?.message || e)); }\n  };\n\n  const returnDeposit = () => Alert.alert('Return deposit?', 'Sends this deposit back to your hot wallet (minus a small fee). No QRs will be valid.', [\n    { text: 'Cancel', style: 'cancel' },\n    { text: 'Return', style: 'destructive', onPress: async () => { setBusy(true); const r = await SQ.sqReturnToHot(); setBusy(false); if (r.error) Alert.alert('Return', r.error); else { Alert.alert('Returned', 'The deposit is going back to your hot wallet.'); setMode('home'); } await reload(); } },\n  ]);\n\n  const onScanned = async (data: string) => {\n    if (scanLock.current) return; scanLock.current = true;\n    try {\n      if (mode === 'verify') {\n        const r = await SQ.sqVerifyAndForget(data);\n        if (r.error) { Alert.alert('Not yet', r.error); return; }\n        Alert.alert('Saved to the vault', 'The key is deleted. Your printed QRs are now the only way to move these coins, and they can only pay your hot wallet. Keep the two copies in different places.');\n        setMode('home'); await reload(); return;\n      }\n      const c = await SQ.sqCheckQr(data);\n      if (c.error || !c.info) { Alert.alert('Savings QR', c.error || 'Not valid'); return; }\n      const i = c.info;\n      const warn = i.paysHot ? '' : '\\n\\nWARNING: this QR pays wallet …' + i.hotLast6 + ', not your current wallet. Continue only if you still have that wallet\\'s seed.';\n      Alert.alert('Move to hot wallet?', fmt(i.outSompi) + ' KAS will go to your hot wallet …' + i.hotLast6 + '.' + warn, [\n        { text: 'Cancel', style: 'cancel' },\n        { text: 'Send', onPress: async () => { setBusy(true); const r = await SQ.sqSpend(i); setBusy(false); if (r.error) Alert.alert(r.maybe ? 'Check before retrying' : 'Failed', r.error); else Alert.alert('Sent', 'Coins are on their way to your hot wallet.'); setMode('home'); await reload(); } },\n      ]);\n    } finally { setTimeout(() => { scanLock.current = false; }, 1500); }\n  };\n\n  const unspent = rows.filter((r) => r.status !== 'spent');\n  const total = unspent.reduce((a, r) => a + BigInt(r.outSompi), 0n);\n  const camera = (\n    _cam?.CameraView && camOk ? (\n      <View style={st.cam}><_cam.CameraView style={{ flex: 1 }} barcodeScannerSettings={{ barcodeTypes: ['qr'] }}\n        onBarcodeScanned={(e: any) => { const d = String(e?.data || ''); if (d.startsWith('KVSQ1|')) onScanned(d); }} /></View>\n    ) : (<TouchableOpacity style={st.sec} onPress={askCamera}><Text style={st.secT}>Turn on camera</Text></TouchableOpacity>)\n  );\n\n  if (mode === 'add') return (\n    <ScrollView contentContainerStyle={st.c}>\n      <Text style={st.t}>Add to vault</Text>\n      <Text style={st.b}>Moves KAS from your hot wallet into printed Savings QRs. After you print and scan one back, the key is deleted: the paper is the only way to move these coins, and only into your hot wallet.</Text>\n      <Text style={st.l}>Amount (KAS)</Text>\n      <TextInput style={st.in} value={amount} onChangeText={setAmount} keyboardType=\"decimal-pad\" placeholder=\"e.g. 500\" placeholderTextColor=\"#78716C\" />\n      <Text style={st.l}>Split into how many QRs (1-10)</Text>\n      <TextInput style={st.in} value={count} onChangeText={setCount} keyboardType=\"number-pad\" />\n      <Text style={st.s}>Each QR returns its share minus a small network fee (~0.005 KAS). A split also pays one small fee.</Text>\n      <TouchableOpacity style={[st.pri, busy && { opacity: 0.5 }]} disabled={busy} onPress={startDeposit}>{busy ? <ActivityIndicator color=\"#000\" /> : <Text style={st.priT}>Deposit</Text>}</TouchableOpacity>\n      <TouchableOpacity style={st.sec} onPress={() => setMode('home')}><Text style={st.secT}>Back</Text></TouchableOpacity>\n    </ScrollView>\n  );\n\n  if (mode === 'progress') return (\n    <ScrollView contentContainerStyle={st.c}>\n      <Text style={st.t}>Preparing your QRs</Text>\n      <ActivityIndicator color=\"#D4AF37\" style={{ marginVertical: 20 }} />\n      <Text style={st.b}>{msg || 'Working…'}</Text>\n      <TouchableOpacity style={st.sec} onPress={() => setMode('home')}><Text style={st.secT}>Leave (safe - resume later)</Text></TouchableOpacity>\n      <TouchableOpacity style={st.sec} onPress={returnDeposit}><Text style={st.secT}>Return deposit to hot wallet</Text></TouchableOpacity>\n    </ScrollView>\n  );\n\n  if (mode === 'print') return (\n    <ScrollView contentContainerStyle={st.c}>\n      <Text style={st.t}>Print your Savings QRs</Text>\n      <Text style={st.b}>{(session?.qrs?.length || 0)} QR{(session?.qrs?.length || 0) > 1 ? 's' : ''} ready. Print TWO copies and store them in different places. Losing every copy of a QR loses its coins.</Text>\n      <TouchableOpacity style={st.pri} onPress={printSheet}><Text style={st.priT}>Print sheet</Text></TouchableOpacity>\n      <TouchableOpacity style={st.sec} onPress={() => setMode('verify')}><Text style={st.secT}>I printed two copies → Verify</Text></TouchableOpacity>\n      <TouchableOpacity style={st.sec} onPress={returnDeposit}><Text style={st.secT}>Cancel: return deposit</Text></TouchableOpacity>\n    </ScrollView>\n  );\n\n  if (mode === 'verify' || mode === 'scan') return (\n    <ScrollView contentContainerStyle={st.c}>\n      <Text style={st.t}>{mode === 'verify' ? 'Scan one printed QR' : 'Scan a Savings QR'}</Text>\n      <Text style={st.b}>{mode === 'verify' ? 'Scan any QR from the PAPER (not a screen). This proves the print is readable; then the key is deleted.' : 'The coins move to your hot wallet. Nothing else is possible with a Savings QR.'}</Text>\n      {camera}\n      {busy ? <ActivityIndicator color=\"#D4AF37\" /> : null}\n      <TouchableOpacity style={st.sec} onPress={() => setMode(mode === 'verify' ? 'print' : 'home')}><Text style={st.secT}>Back</Text></TouchableOpacity>\n    </ScrollView>\n  );\n\n  return (\n    <ScrollView contentContainerStyle={st.c}>\n      <Text style={st.t}>Savings QR vault</Text>\n      <Text style={st.big}>{fmt(total)} KAS</Text>\n      <Text style={st.s}>{unspent.length} unspent QR{unspent.length === 1 ? '' : 's'} · no keys stored</Text>\n      {session ? (\n        <View style={st.card}>\n          <Text style={st.cardH}>Deposit in progress ({session.stage})</Text>\n          <TouchableOpacity style={st.pri} onPress={() => setMode(session.stage === 'signed' ? 'print' : 'progress')}><Text style={st.priT}>Continue</Text></TouchableOpacity>\n          <TouchableOpacity style={st.sec} onPress={returnDeposit}><Text style={st.secT}>Return deposit to hot wallet</Text></TouchableOpacity>\n        </View>\n      ) : (\n        <TouchableOpacity style={st.pri} onPress={() => { if (SQ.sqTutorial()) { Alert.alert('Real mode only', 'Savings QR needs Real mode.'); return; } setMode('add'); }}><Text style={st.priT}>Add to vault</Text></TouchableOpacity>\n      )}\n      <TouchableOpacity style={st.pri} onPress={() => setMode('scan')}><Text style={st.priT}>Spend: scan a QR</Text></TouchableOpacity>\n      {oldVault && oldVault.sompi > 0n ? (\n        <View style={st.card}>\n          <Text style={st.cardH}>Old card + paper vault: {fmt(oldVault.sompi)} KAS</Text>\n          <Text style={st.s}>This vault type is retired. Move its coins to your hot wallet (needs your vault cards loaded and your paper key), then put them in Savings QRs.</Text>\n          <TouchableOpacity style={st.pri} onPress={async () => setOldSweep({ to: await SQ.sqHotAddress(), kas: oldVault.sweepKas })}><Text style={st.priT}>Move funds to hot wallet</Text></TouchableOpacity>\n        </View>\n      ) : null}\n      {oldVault && oldSweep ? (\n        <VaultQRSignScreen visible vault={oldVault.vault} initialRecipient={oldSweep.to} initialAmountKas={oldSweep.kas}\n          getPrivateKeyHex={() => require('./kasvillage_cold_wallet').vaultCardKeyHex()}\n          onClose={() => { setOldSweep(null); reload(); }} onSuccess={() => { setOldSweep(null); reload(); }} />\n      ) : null}\n      {rows.slice().reverse().map((r) => (\n        <View key={r.id} style={st.row}>\n          <Text style={st.rowT}>{fmt(r.outSompi)} KAS · {r.label}</Text>\n          <Text style={[st.s, { color: r.status === 'spent' ? '#78716C' : r.status === 'unspent' ? '#86EFAC' : '#FBBF24' }]}>{r.status || 'checking'} · {new Date(r.createdAt).toISOString().slice(0, 10)} · pays …{r.hotLast6}</Text>\n        </View>\n      ))}\n      <TouchableOpacity style={st.sec} onPress={onClose}><Text style={st.secT}>Close</Text></TouchableOpacity>\n    </ScrollView>\n  );\n};\n\nconst st = StyleSheet.create({\n  c: { padding: 20, paddingTop: 56, backgroundColor: '#1C1917', flexGrow: 1 },\n  t: { color: '#F5F5F4', fontSize: 22, fontWeight: '800', marginBottom: 10 },\n  big: { color: '#D4AF37', fontSize: 32, fontWeight: '800' },\n  b: { color: '#D6D3D1', fontSize: 14, lineHeight: 20, marginBottom: 12 },\n  s: { color: '#A8A29E', fontSize: 12, marginBottom: 6 },\n  l: { color: '#D6D3D1', fontSize: 13, fontWeight: '700', marginTop: 8 },\n  in: { borderWidth: 1, borderColor: '#78716C', borderRadius: 8, padding: 10, color: '#F5F5F4', marginVertical: 6 },\n  pri: { backgroundColor: '#D4AF37', borderRadius: 10, padding: 14, alignItems: 'center', marginTop: 12 },\n  priT: { color: '#000', fontWeight: '800' },\n  sec: { borderWidth: 1, borderColor: '#78716C', borderRadius: 10, padding: 12, alignItems: 'center', marginTop: 10 },\n  secT: { color: '#F5F5F4', fontWeight: '600' },\n  card: { borderWidth: 1, borderColor: '#D4AF37', borderRadius: 12, padding: 12, marginTop: 12 },\n  cardH: { color: '#F5F5F4', fontWeight: '700' },\n  row: { borderBottomWidth: 1, borderBottomColor: '#292524', paddingVertical: 10 },\n  rowT: { color: '#F5F5F4', fontWeight: '600' },\n  cam: { height: 280, borderRadius: 12, overflow: 'hidden', marginVertical: 10 },\n});\n\nexport default SavingsQRScreen;\n"
};
