let changed = 0;
for (const [f, src] of Object.entries(FILES)) {
  if (fs.existsSync(f) && fs.readFileSync(f, 'utf8') === src) { console.log('same   ', f); continue; }
  if (fs.existsSync(f)) fs.copyFileSync(f, f + '.bak_savingsqr');
  fs.writeFileSync(f, src); changed++; console.log('wrote  ', f);
}
for (const [f, a, b] of PATCHES) {
  let s = fs.readFileSync(f, 'utf8');
  if (s.includes(b)) { console.log('already', f, '|', a.trim().slice(0, 40)); continue; }
  const n = s.split(a).length - 1;
  if (n !== 1) { console.error('ANCHOR ' + (n ? 'NOT UNIQUE' : 'MISSING') + ' in ' + f + ':\n' + a); process.exit(1); }
  if (!fs.existsSync(f + '.bak_savingsqr')) fs.copyFileSync(f, f + '.bak_savingsqr');
  fs.writeFileSync(f, s.replace(a, b)); changed++; console.log('patched', f, '|', a.trim().slice(0, 40));
}

// dependencies: expo-print (native, needs a new dev build) + qrcode (was only indirect)
{
  const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
  const missing = ['expo-print', 'qrcode'].filter((d) => !(pkg.dependencies || {})[d]);
  if (missing.length) {
    console.log('installing', missing.join(' '), '...');
    require('child_process').execSync('npx expo install ' + missing.join(' '), { stdio: 'inherit' });
    const p2 = JSON.parse(fs.readFileSync('package.json', 'utf8'));
    const still = missing.filter((d) => !(p2.dependencies || {})[d]);
    if (still.length) { console.error('VALIDATION FAILED: could not add ' + still.join(' ') + ' to package.json'); process.exit(1); }
  } else console.log('deps   ', 'expo-print + qrcode present');
}
// validate
const nav = fs.readFileSync('AppNaviagator.tsx', 'utf8'), gv = fs.readFileSync('GenerateVaultScreen.tsx', 'utf8');
const ok = nav.includes("case 'savings_qr'") && nav.includes("onSavingsQR={() => setScreen('savings_qr')}") && gv.includes('onSavingsQR,') && !gv.includes('Also require a paper key') && gv.includes('sqVaultReplaceGuard') && fs.readFileSync('SavingsQRScreen.tsx','utf8').includes('Move funds to hot wallet');
console.log(ok ? 'OK - ' + changed + ' change(s). Next: new dev build (expo-print is native), test on testnet.' : 'VALIDATION FAILED');
process.exit(ok ? 0 : 1);
